import {CURRICULUM,QUIZ_BANK,OFFICIAL_PROGRAMME,findConcept as baseFindConcept} from './curriculum.js?v=3';
import {loadState,saveState,isIndexedDbAvailable,freshState} from './db.js?v=3';

const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const app=$('#appMain'), dialog=$('#dialog'), dialogContent=$('#dialogContent');
let state, curriculum, route='welcome', selectedConceptId=null, selectedDeckId=null, reviewQueue=[], reviewIndex=0, isFlipped=false, activeQuiz=null, quizTimer=null, toastTimer, installPrompt=null, roadmapQuery='', roadmapTrack='extended';
const esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const pct=(a,b)=>b?Math.round(a/b*100):0;
const fmtDate=(d)=>d?new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'—';
const fmtRelative=(d)=>{if(!d)return 'just now';const days=Math.floor((Date.now()-new Date(d).getTime())/86400000);return days<1?'today':days===1?'yesterday':`${days} days ago`};
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2700)}
function persist(){saveState(state)}
function logActivity(label,icon='✓',conceptId=''){state.activity.unshift({id:uid(),label,icon,conceptId,at:new Date().toISOString()});state.activity=state.activity.slice(0,40);persist()}
function status(id){return state.progress[id]||'not-started'}
function statusLabel(s){return ({'not-started':'Not started',learning:'Learning',mastered:'Mastered'})[s]||'Not started'}
function countStats(){const concepts=currentConcepts(),all=concepts.length,mastered=concepts.filter(c=>state.progress[c.id]==='mastered').length,learning=concepts.filter(c=>state.progress[c.id]==='learning').length;const compTotal=concepts.reduce((n,c)=>n+c.competencies.length,0),compDone=concepts.reduce((n,c)=>n+(state.competencyProgress[c.id]||[]).filter(Boolean).length,0);return {all,mastered,learning,notStarted:all-mastered-learning,compTotal,compDone}}
function activeCurriculum(){return curriculum||CURRICULUM}
function setRoute(next){route=next;history.replaceState(null,'',`#${next}`);render();window.scrollTo({top:0,behavior:'smooth'})}
function profileTop(){const full=state.profile.fullName||'Your profile';$('#profileNameTop').textContent=full.split(' ')[0];$('#avatarLetter').textContent=(full.trim()[0]||'Y').toUpperCase();document.body.classList.toggle('dark',state.settings.theme==='dark');$$('.desktop-nav a').forEach(a=>a.toggleAttribute('aria-current',a.dataset.route===route))}
function shell(title,kicker,subtitle='',actions=''){return `<div class="app-shell"><header class="page-heading"><div><div class="eyebrow">${esc(kicker)}</div><h1>${title}</h1></div><div>${subtitle?`<p>${esc(subtitle)}</p>`:''}${actions?`<div class="action-row" style="margin-top:12px">${actions}</div>`:''}</div></header><div id="pageContent"></div></div>`}
function currentConcepts(){return activeCurriculum().flatMap(p=>p.modules.flatMap(m=>m.concepts))}
function findConcept(id){return currentConcepts().find(c=>c.id===id)||baseFindConcept(id)}
function moduleProgress(mod){const cs=mod.concepts,done=cs.filter(c=>status(c.id)==='mastered').length;return {done,total:cs.length,percent:pct(done,cs.length)}}
function phaseProgress(phase){const mods=phase.modules,all=mods.flatMap(m=>m.concepts),done=all.filter(c=>status(c.id)==='mastered').length;return {done,total:all.length,percent:pct(done,all.length)}}

function renderWelcome(){
 app.innerHTML=`<main class="welcome-page"><section class="welcome-hero"><div class="welcome-copy"><div class="eyebrow"><span class="live-dot"></span> A LEARNING WORKSPACE FOR YOUCODE</div><h1>Build skill.<br>Build <span class="serif-accent">confidence.</span></h1><p>One clear place to understand the first-year programme, practice individual concepts, and make room for the developer you want to become.</p><div class="action-row"><a class="button button-dark" href="#roadmap" data-route="roadmap">Explore the roadmap <span>↘</span></a><a class="text-link" href="#home" data-route="home">Open my workspace ↗</a></div><div class="welcome-caption"><span class="micro">OFFICIAL PHASE NAMES · VERIFIED</span><span class="micro">EXTENDED STUDY · CLEARLY LABELED</span></div></div><div class="welcome-art" aria-label="An illustrated seven-step learning path"><div class="art-paper" data-parallax-speed="0.12"></div><div class="art-ring" data-parallax-speed="-0.2"></div><div class="art-label" data-parallax-speed="0.32">MAKE<br>IT<br>YOURS<span>✳</span></div><div class="art-path">${OFFICIAL_PROGRAMME.phases.map((p,i)=>`<div class="art-node" data-parallax-speed="${((i%3)-1)*.08}"><b>${String(i+1).padStart(2,'0')}</b><span>${esc(p.title)}</span></div>`).join('')}</div><div class="art-foot micro">FIG. 01 / A YEAR IN MOTION</div></div></section><section class="welcome-statband"><div><strong>07</strong><span>verified official phase titles</span></div><div><strong>02</strong><span>distinct learning tracks</span></div><div><strong>∞</strong><span>room for your own path</span></div></section><section class="welcome-tracks" data-reveal><div class="welcome-intro"><div class="eyebrow">A MAP WITH ITS SOURCES IN VIEW</div><h2>Know what’s official.<br><span class="serif-accent">Choose what’s next.</span></h2><p>The public YouCode page names the phases and describes the first-year approach. The detailed study map is an extension to help you practice; it is not presented as an official module list.</p><a href="#roadmap" class="text-button" data-route="roadmap">See both tracks →</a></div><article class="track-editorial official-editorial" data-reveal><span class="micro">01 / OFFICIAL YOUCODE</span><h3>The published programme.</h3><p>Seven phase headings and the broad project-based, self-learning approach described by YouCode.</p><a class="button button-blue" href="#roadmap" data-action="roadmap-track" data-id="official">Read verified details <span>↗</span></a></article><article class="track-editorial extended-editorial" data-reveal data-parallax-speed="0.06"><span class="micro">02 / EXTENDED DEVELOPER ROADMAP</span><h3>Extra detail for practice.</h3><p>Topics, competencies, examples, exercises, resources, flashcards, and quizzes that help you build confidence around the phase themes.</p><a class="button button-acid" href="#roadmap" data-action="roadmap-track" data-id="extended">Explore recommended topics <span>↗</span></a></article></section><section class="welcome-loop" data-reveal><div class="micro">LEARN / PRACTICE / RECALL / REFLECT</div><h2>A steady rhythm beats a perfect plan.</h2><div class="loop-line"><div><b>01</b><strong>Understand</strong><p>Read a clear concept guide and follow its prerequisites.</p></div><div><b>02</b><strong>Practice</strong><p>Try an exercise and check the competency list against your work.</p></div><div><b>03</b><strong>Recall</strong><p>Review with spaced flashcards and short quizzes.</p></div><div><b>04</b><strong>Build</strong><p>Connect a concept to a project or your own learning task.</p></div></div></section><footer class="welcome-footer"><span class="brand"><span class="brand-icon">L.</span><span>learn<span class="slash">/</span>youcode</span></span><span class="micro">MADE TO GROW WITH YOU</span><a href="${esc(OFFICIAL_PROGRAMME.sourceUrl)}" target="_blank" rel="noopener noreferrer">YouCode programme ↗</a></footer></main>`;
}

function renderHomeContent(){const s=countStats(),paths=activeCurriculum(),activities=state.activity.slice(0,5),recent=activities.length?activities.map(a=>`<div class="activity"><span class="activity-mark">${esc(a.icon)}</span><span>${esc(a.label)}</span><time>${fmtRelative(a.at)}</time></div>`).join(''):'<div class="empty">Your learning activity will show up here.</div>';const due=state.flashcards.filter(c=>!c.nextReview||new Date(c.nextReview)<=new Date()).length;
 app.innerHTML=shell('Make your next move <span class="serif-accent">count.</span>','Your learning workspace','A living map of the first-year YouCode phases, plus room for the skills you want to explore.',`<a class="button button-dark" href="#roadmap">Continue roadmap <span>↗</span></a><button class="button button-acid" data-action="new-task">Add a task <span>＋</span></button>`)+`<section class="grid dashboard-grid"><div><div class="panel hero-panel shadow"><div class="eyebrow">YEAR 1 / 7 VERIFIED PHASE TITLES</div><h1>Learn the idea.<br>Practice the skill.</h1><p>Work through the roadmap at your own pace, track the things you can do, and shape a learning path that fits you.</p></div><div class="stat-grid"><div class="stat"><strong>${s.all}</strong><span>Total concepts</span></div><div class="stat"><strong>${s.mastered}</strong><span>Mastered</span></div><div class="stat"><strong>${s.learning}</strong><span>Learning</span></div><div class="stat"><strong>${s.compDone}<small>/${s.compTotal}</small></strong><span>Competencies checked</span></div></div><section class="panel"><div class="section-title" style="margin-top:0"><h2>Your first year</h2><span class="micro">${s.mastered} / ${s.all} MASTERED · ${pct(s.mastered,s.all)}%</span></div><div class="progress-track" aria-label="Overall mastery progress"><i style="width:${pct(s.mastered,s.all)}%"></i></div><div class="phase-overview">${paths.map(p=>{const pr=phaseProgress(p);return `<a class="phase-mini" href="#roadmap" data-action="open-phase" data-id="${p.id}"><span class="phase-num">${String(p.index+1).padStart(2,'0')}</span><span><small>${pr.done}/${pr.total} CONCEPTS · ${pr.percent}%</small><strong>${esc(p.title)}</strong></span></a>`}).join('')}</div></section></div><aside><section class="panel shadow"><div class="section-title" style="margin-top:0"><h2>Next up</h2><span class="tag">${due} CARDS DUE</span></div><p>Keep a small practice rhythm. A short review today makes the ideas easier to retrieve later.</p><div class="action-row"><a class="button button-dark" href="#flashcards">Review flashcards <span>↗</span></a><a class="button" href="#quizzes">Take a quiz</a></div><hr class="section-rule"><div class="micro">PERSONAL GOAL</div><p><strong>${esc(state.profile.goal||'Choose a learning goal')}</strong></p><a href="#profile" class="text-button">Edit profile and goals →</a></section><section class="panel" style="margin-top:15px"><div class="section-title" style="margin-top:0"><h2>Recent activity</h2><span class="micro">THIS DEVICE</span></div><div class="activity-list">${recent}</div><p class="fine">Progress is stored privately in this browser. It is available offline on this device.</p></section></aside></section>`;
}

function renderHome(){
 renderHomeContent();
 const active=currentConcepts().filter(c=>status(c.id)==='learning').slice(0,3);
 const visited=[...new Map(state.activity.filter(a=>a.conceptId&&findConcept(a.conceptId)).map(a=>[a.conceptId,a])).values()].slice(0,3);
 const tasks=state.tasks.filter(t=>t.status!=='done').sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')).slice(0,3);
 const quiz=state.quizAttempts[0];
 const conceptRows=items=>items.length?items.map(c=>`<button class="focus-link" data-action="concept" data-id="${c.id}">${esc(c.title)} <span>↗</span></button>`).join(''):'<p class="fine">Nothing here yet. Open a roadmap concept to begin.</p>';
 const focus=`<section class="panel dashboard-focus" data-reveal><div class="section-title" style="margin-top:0"><h2>Keep your momentum</h2><span class="micro">YOUR RECENT LEARNING</span></div><div class="dashboard-focus-grid"><section><h3>Active learning</h3>${conceptRows(active)}</section><section><h3>Recently visited</h3>${conceptRows(visited.map(a=>findConcept(a.conceptId)).filter(Boolean))}</section><section><h3>Next goals</h3>${tasks.length?tasks.map(t=>`<a class="focus-link" href="#tasks" data-route="tasks">${esc(t.title)} <span>${t.dueDate?esc(fmtDate(t.dueDate)):'Task'} ↗</span></a>`).join(''):'<p class="fine">Add a personal task to plan your next step.</p>'}</section><section><h3>Latest quiz</h3>${quiz?`<p class="focus-score"><strong>${quiz.score}%</strong><span>${quiz.correct}/${quiz.total} correct<br>${fmtRelative(quiz.at)}</span></p><a class="text-button" href="#quizzes" data-route="quizzes">Review your results →</a>`:'<p class="fine">No attempts yet. Use a short quiz to check your recall.</p><a class="text-button" href="#quizzes" data-route="quizzes">Open quizzes →</a>'}</section></div></section>`;
 app.querySelector('.dashboard-grid')?.insertAdjacentHTML('afterend',focus);
}

function renderRoadmapLegacy(){const paths=activeCurriculum();app.innerHTML=shell('The whole year, <span class="serif-accent">piece by piece.</span>','01 / Official roadmap','Expand a phase, open its modules, then choose any concept to study it, set your status, and check off the things you can do.',`<button class="button button-dark" data-action="new-task">＋ Personal task</button>`)+`<div class="roadmap-tools"><label class="search-wrap"><span aria-hidden="true">⌕</span><input id="roadmapSearch" type="search" value="${esc(roadmapQuery)}" placeholder="Find a phase, module, concept…" aria-label="Search roadmap"></label><span class="tag">7 OFFICIAL PHASE TITLES</span></div><div class="two-col"><section id="phaseTree">${paths.map((p,pi)=>{const pr=phaseProgress(p),phaseText=[p.title,p.focus,p.overview,...p.modules.flatMap(m=>[m.name,...m.concepts.map(c=>c.title)])].join(' ').toLowerCase();if(roadmapQuery&&!phaseText.includes(roadmapQuery.toLowerCase()))return '';const defaultOpen=pi===0;return `<details class="phase-accordion" id="${p.id}" ${defaultOpen?'open':''}><summary class="phase-summary"><span class="phase-num">${String(pi+1).padStart(2,'0')}</span><span><small>${esc(p.duration)} · ${pr.done}/${pr.total} MASTERED</small><strong>${esc(p.title)}</strong></span><span class="phase-progress">${pr.percent}%</span><span aria-hidden="true">⌄</span></summary><div class="phase-body"><span class="tag">${esc(p.source)}</span><h3>${esc(p.focus)}</h3><p>${esc(p.overview)}</p><div class="phase-facts"><div class="fact"><b>OBJECTIVES</b><span>${p.objectives.map(esc).join(' · ')}</span></div><div class="fact"><b>PREREQUISITES</b><span>${p.prerequisites.map(esc).join(' · ')}</span></div><div class="fact"><b>ESTIMATED TIME</b><span>${esc(p.duration)}</span></div><div class="fact"><b>PRACTICE</b><span>${p.activities.map(esc).join(' · ')}</span></div><div class="fact"><b>PROJECT / DELIVERABLE</b><span>${esc(p.project)}</span></div><div class="fact"><b>COMPLETION CRITERIA</b><span>${esc(p.criteria)}</span></div></div>${p.modules.map((m,mi)=>{const mp=moduleProgress(m),q=m.concepts.filter(c=>`${m.name} ${c.title}`.toLowerCase().includes(roadmapQuery.toLowerCase()));if(roadmapQuery&&!q.length&&!m.name.toLowerCase().includes(roadmapQuery.toLowerCase()))return '';return `<details class="module" ${mi===0?'open':''}><summary>${esc(m.name)} <span>${mp.done}/${mp.total} MASTERED · ${esc(m.duration)}</span></summary><p class="fine" style="padding:0 12px">${esc(m.description)} ${m.supplementary?'<span class="tag">SUPPLEMENTARY</span>':''}</p><div class="concept-grid">${m.concepts.filter(c=>!roadmapQuery||`${c.title} ${m.name}`.toLowerCase().includes(roadmapQuery.toLowerCase())).map(c=>`<button class="concept-link" data-action="concept" data-id="${c.id}"><i class="status-dot ${status(c.id)}"></i><span>${esc(c.title)}</span>${c.supplementary?'<span class="tag">EXTRA</span>':''}</button>`).join('')}</div></details>`}).join('')}</div></details>`}).join('')}</section><aside class="panel detail-panel"><div class="eyebrow">HOW TO USE THIS MAP</div><h2>Competence over clicks.</h2><p>A concept only becomes mastered when you choose that status. Opening a lesson does not complete it.</p><hr class="section-rule"><ul class="checklist"><li>🟢 <span><strong>Not started</strong> — neutral and ready when you are.</span></li><li>🟠 <span><strong>Learning</strong> — you are practicing this now.</span></li><li>✅ <span><strong>Mastered</strong> — self-reported; no quiz is required.</span></li></ul><p>Competencies and the five-item mastery reflection are tracked separately for every concept.</p><button class="button button-acid" data-action="new-card">＋ Create a flashcard</button><p class="fine">The seven phase names are identified as official. Detailed modules, concepts, exercises, and project ideas are recommended study material unless YouCode confirms them.</p></aside></div>`;
 $('#roadmapSearch')?.addEventListener('input',e=>{roadmapQuery=e.target.value;const y=window.scrollY;renderRoadmap();window.scrollTo(0,y);$('#roadmapSearch')?.focus();$('#roadmapSearch').setSelectionRange(roadmapQuery.length,roadmapQuery.length)});
}

function renderTopicGroups(module){const map=new Map();for(const concept of module.concepts){if(roadmapQuery&&!`${concept.title} ${concept.topic}`.toLowerCase().includes(roadmapQuery.toLowerCase()))continue;const list=map.get(concept.topic)||[];list.push(concept);map.set(concept.topic,list)}return [...map].map(([topic,items])=>`<details class="topic-node" open><summary><span>${esc(topic)}</span><small>${items.length} CONCEPT${items.length===1?'':'S'}</small></summary><div class="concept-grid">${items.map(c=>`<button class="concept-link" data-action="concept" data-id="${c.id}"><i class="status-dot ${status(c.id)}"></i><span>${esc(c.title)}</span><span class="concept-source">RECOMMENDED</span></button>`).join('')}</div></details>`).join('')}

function renderRoadmap(){
 const paths=activeCurriculum(),isOfficial=roadmapTrack==='official';
 const tabs=`<div class="track-tabs" role="tablist" aria-label="Learning track"><button role="tab" aria-selected="${isOfficial}" class="track-tab ${isOfficial?'active':''}" data-action="roadmap-track" data-id="official"><span>01</span><strong>Official YouCode</strong><small>Verified public material only</small></button><button role="tab" aria-selected="${!isOfficial}" class="track-tab ${!isOfficial?'active':''}" data-action="roadmap-track" data-id="extended"><span>02</span><strong>Extended developer roadmap</strong><small>Recommended learning detail</small></button></div>`;
 const journey=`<nav class="journey-map" aria-label="Seven year-one phases">${paths.map((p,i)=>`<button class="journey-node ${phaseProgress(p).percent===100?'complete':''}" data-action="jump-phase" data-id="${p.id}" aria-label="Phase ${i+1}: ${esc(p.title)}"><span>${String(i+1).padStart(2,'0')}</span><small>${esc(p.title)}</small></button>`).join('')}</nav>`;
 const officialTree=OFFICIAL_PROGRAMME.phases.map((p,i)=>`<details class="phase-accordion" id="${p.id.replace('official-','')}" data-reveal ${i===0?'open':''}><summary class="phase-summary"><span class="phase-num">${String(i+1).padStart(2,'0')}</span><span><small>VERIFIED PUBLIC TITLE</small><strong>${esc(p.title)}</strong></span><span class="phase-progress">Official</span><span aria-hidden="true">⌄</span></summary><div class="phase-body"><p>${esc(p.detail)}</p><a class="source-link" href="${esc(OFFICIAL_PROGRAMME.sourceUrl)}" target="_blank" rel="noopener noreferrer">View YouCode programme ↗</a></div></details>`).join('');
 const extendedTree=paths.map((p,pi)=>{const pr=phaseProgress(p),phaseText=[p.title,p.focus,p.overview,...p.modules.flatMap(m=>[m.name,...m.concepts.map(c=>`${c.title} ${c.topic}`)])].join(' ').toLowerCase();if(roadmapQuery&&!phaseText.includes(roadmapQuery.toLowerCase()))return '';return `<details class="phase-accordion" id="${p.id}" data-reveal ${pi===0?'open':''}><summary class="phase-summary"><span class="phase-num">${String(pi+1).padStart(2,'0')}</span><span><small>OFFICIAL TITLE · ${pr.done}/${pr.total} MASTERED</small><strong>${esc(p.title)}</strong></span><span class="phase-progress">${pr.percent}%</span><span aria-hidden="true">⌄</span></summary><div class="phase-body"><div class="source-ribbon"><span class="tag">OFFICIAL TITLE VERIFIED</span><span class="tag status-pending">DETAIL BELOW IS RECOMMENDED</span></div><h3>${esc(p.focus)}</h3><p>${esc(p.overview)}</p><div class="phase-facts"><div class="fact"><b>RECOMMENDED OBJECTIVES</b><span>${p.objectives.map(esc).join(' · ')}</span></div><div class="fact"><b>ASSUMED PREREQUISITES</b><span>${p.prerequisites.map(esc).join(' · ')}</span></div><div class="fact"><b>ESTIMATED STUDY TIME</b><span>${esc(p.duration)} · planning estimate</span></div><div class="fact"><b>SUGGESTED PRACTICE</b><span>${p.activities.map(esc).join(' · ')}</span></div><div class="fact"><b>PROJECT IDEA</b><span>${esc(p.project)}</span></div><div class="fact"><b>SELF-CHECK CRITERIA</b><span>${esc(p.criteria)}</span></div></div>${p.modules.map((m,mi)=>{const mp=moduleProgress(m);if(roadmapQuery&&!`${m.name} ${m.concepts.map(c=>`${c.title} ${c.topic}`).join(' ')}`.toLowerCase().includes(roadmapQuery.toLowerCase()))return '';return `<details class="module" ${mi===0?'open':''}><summary><span>${esc(m.name)}</span><span>${mp.done}/${mp.total} MASTERED · ${esc(m.duration)}</span></summary><p class="fine module-description">${esc(m.description)} ${m.supplementary?'<span class="tag">OPTIONAL TECHNOLOGY</span>':''}</p>${renderTopicGroups(m)}</details>`}).join('')}<p class="fine source-boundary">These topics are an extended study recommendation mapped to a related official phase heading. YouCode’s public page does not confirm this mapping as an official module list.</p></div></details>`}).join('');
 app.innerHTML=shell('A year you can <span class="serif-accent">navigate.</span>','01 / Learning roadmap',isOfficial?'The official public page confirms seven phase titles and a broad first-year approach. It does not publish the detailed module breakdown.':'Move through the recommended topic order, open a concept, and track what you can demonstrate.',`<button class="button button-dark" data-action="new-task">＋ Personal task</button>`)+`${tabs}${journey}<div class="roadmap-tools"><label class="search-wrap"><span aria-hidden="true">⌕</span><input id="roadmapSearch" type="search" value="${esc(roadmapQuery)}" placeholder="Find a phase, topic, concept…" aria-label="Search roadmap"></label><span class="source-stamp">SOURCE CHECKED ${esc(OFFICIAL_PROGRAMME.verifiedDate)}</span></div>${isOfficial?`<section class="programme-note" data-reveal><div><span class="micro">YEAR ONE · OFFICIAL SUMMARY</span><h2>${esc(OFFICIAL_PROGRAMME.yearOne)}</h2><p>${esc(OFFICIAL_PROGRAMME.boundary)}</p><a class="source-link" href="${esc(OFFICIAL_PROGRAMME.sourceUrl)}" target="_blank" rel="noopener noreferrer">Read the official YouCode programme ↗</a></div><aside><span class="micro">PUBLISHED PEDAGOGY</span><ul>${OFFICIAL_PROGRAMME.pedagogy.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></aside></section><section id="phaseTree">${officialTree}</section>`:`<div class="two-col"><section id="phaseTree">${extendedTree||'<div class="empty">No matching recommendations. Try a shorter search.</div>'}</section><aside class="panel detail-panel" data-reveal><div class="eyebrow">READING THE ROADMAP</div><h2>Official names.<br>Extended study detail.</h2><p>The phase titles come from the public YouCode page. The modules, topics, durations, objectives, projects, and competencies shown in this track are recommendations and planning estimates.</p><hr class="section-rule"><div class="legend-item"><i class="status-dot"></i><span>Not started</span></div><div class="legend-item"><i class="status-dot learning"></i><span>Learning</span></div><div class="legend-item"><i class="status-dot mastered"></i><span>Mastered by self-report</span></div><p class="fine">A concept is not complete just because it was opened. Its competency indicators and mastery reflection are tracked separately.</p><button class="button button-acid" data-action="new-card">＋ Create a flashcard</button></aside></div>`}`;
 $('#roadmapSearch')?.addEventListener('input',e=>{roadmapQuery=e.target.value;const y=window.scrollY;renderRoadmap();window.scrollTo(0,y);$('#roadmapSearch')?.focus();$('#roadmapSearch').setSelectionRange(roadmapQuery.length,roadmapQuery.length)});
 $('#phaseTree')?.addEventListener('toggle',e=>{if(e.target.matches('.phase-accordion')&&e.target.open)e.target.classList.add('expanded')},true);
 initMotion();
}

function renderTasks(){const tasks=state.tasks,done=tasks.filter(t=>t.status==='done').length,filter=$('#taskFilterValue')?.value||'all';let list=tasks.filter(t=>filter==='all'||t.status===filter);app.innerHTML=shell('Your path, <span class="serif-accent">your rules.</span>','02 / My tasks','Independent learning goals live alongside the official roadmap and never change it.',`<button class="button button-dark" data-action="new-task">＋ Add a learning task</button>`)+`<section class="panel"><div class="stat-grid"><div class="stat"><strong>${tasks.length}</strong><span>Tasks</span></div><div class="stat"><strong>${done}</strong><span>Completed</span></div><div class="stat"><strong>${tasks.filter(t=>t.status==='in-progress').length}</strong><span>In progress</span></div><div class="stat"><strong>${tasks.reduce((n,t)=>n+(Number(t.estimatedMinutes)||0),0)}</strong><span>Planned minutes</span></div></div><div class="task-filters"><label class="micro">FILTER <select class="filter-select" id="taskFilterValue"><option value="all" ${filter==='all'?'selected':''}>All tasks</option><option value="todo" ${filter==='todo'?'selected':''}>Not started</option><option value="in-progress" ${filter==='in-progress'?'selected':''}>In progress</option><option value="done" ${filter==='done'?'selected':''}>Completed</option></select></label><label class="micro">SORT <select class="filter-select" id="taskSort"><option value="due">Due date</option><option value="priority">Priority</option><option value="created">Recently added</option></select></label></div><div class="task-list">${list.length?list.map(t=>`<article class="task-row"><div><h3>${esc(t.title)}</h3><p>${esc(t.description||'No notes yet.')}${t.conceptId?` · linked to ${esc(findConcept(t.conceptId)?.title||'concept')}`:''}</p></div><span class="task-meta">${esc(t.category||'Personal')} · ${esc(t.priority||'Normal')}</span><span class="task-meta">${t.dueDate?`DUE ${esc(fmtDate(t.dueDate))}`:`${Number(t.estimatedMinutes)||0} MIN`}</span><div class="action-row"><select aria-label="Status for ${esc(t.title)}" class="filter-select" data-task-status="${t.id}"><option value="todo" ${t.status==='todo'?'selected':''}>Not started</option><option value="in-progress" ${t.status==='in-progress'?'selected':''}>Learning</option><option value="done" ${t.status==='done'?'selected':''}>Done</option></select><button class="text-button" data-action="edit-task" data-id="${t.id}">Edit</button><button class="text-button" data-action="delete-task" data-id="${t.id}">Delete</button></div></article>`).join(''):'<div class="empty">No tasks in this view. Add a personal task and make it yours.</div>'}</div></section>`;
 $('#taskFilterValue')?.addEventListener('change',renderTasks);$('#taskSort')?.addEventListener('change',e=>{const field=e.target.value;if(field==='priority')state.tasks.sort((a,b)=>({high:0,normal:1,low:2}[a.priority]??1)-({high:0,normal:1,low:2}[b.priority]??1));else if(field==='created')state.tasks.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));else state.tasks.sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));renderTasks()});
}

function dueCards(cards){const now=Date.now();return [...cards].sort((a,b)=>{const ad=a.nextReview?new Date(a.nextReview).getTime():0,bd=b.nextReview?new Date(b.nextReview).getTime():0;const aDue=ad<=now,bDue=bd<=now;if(aDue!==bDue)return aDue?-1:1;if(a.known!==b.known)return a.known?1:-1;return ad-bd})}
function renderFlashcards(){const decks=state.decks,cards=state.flashcards;const selected=decks.find(d=>d.id===selectedDeckId)||decks[0];if(selected)selectedDeckId=selected.id;const deckCards=selected?dueCards(cards.filter(c=>c.deckId===selected.id)):[];const current=deckCards[Math.min(reviewIndex,Math.max(deckCards.length-1,0))];const due=cards.filter(c=>!c.nextReview||new Date(c.nextReview)<=new Date()).length;
 app.innerHTML=shell('Make it stick, <span class="serif-accent">one recall at a time.</span>','03 / Flashcards','Create your own decks, review cards, and let spaced repetition bring the cards you forget back sooner.',`<button class="button" data-action="new-deck">＋ New deck</button><button class="button button-dark" data-action="new-card">＋ Create flashcard</button>`)+`<div class="flashcard-layout"><aside><div class="panel"><div class="section-title" style="margin-top:0"><h2>My decks</h2><span class="tag">${due} DUE</span></div><div class="item-list deck-list">${decks.length?decks.map(d=>{const n=cards.filter(c=>c.deckId===d.id).length;return `<button class="deck-card ${d.id===selectedDeckId?'active':''}" data-action="select-deck" data-id="${d.id}"><span class="phase-num">▤</span><span><strong>${esc(d.name)}</strong><small>${n} CARDS · ${esc(d.description||'Personal deck')}</small></span></button>`}).join(''):'<div class="empty">Create your first deck.</div>'}</div></div><div class="panel" style="margin-top:12px"><div class="micro">SPACED REVIEW</div><h3>${state.reviews.length} reviews recorded</h3><p>Known cards move to a longer interval; unknown cards return soon. Your review history stays on this device.</p><p class="fine">Decks can be personal or linked to a roadmap phase, module, or concept.</p></div></aside><section>${current?`<div class="review-stat">CARD ${Math.min(reviewIndex+1,deckCards.length)} / ${deckCards.length} · ${deckCards.filter(c=>!c.known).length} TO PRACTICE</div><button class="study-card" id="studyCard" aria-label="Flip flashcard"><span class="micro">${isFlipped?'BACK / ANSWER':'FRONT / QUESTION'} · TAP TO FLIP</span><h2>${esc(isFlipped?current.back:current.front)}</h2>${isFlipped&&current.code?`<pre><code>${esc(current.code)}</code></pre>`:''}${current.image?`<img src="${esc(current.image)}" alt="Flashcard image" style="max-width:100%;max-height:180px;object-fit:contain">`:''}<p>${esc((current.tags||[]).map(t=>`#${t}`).join(' '))}</p></button><div class="study-actions"><button class="button" data-action="card-prev">← Previous</button><button class="button" data-action="card-shuffle">Shuffle</button><button class="button" data-action="card-next">Next →</button></div><div class="study-actions"><button class="button button-danger" data-action="card-review" data-known="false">Need to practice</button><button class="button button-acid" data-action="card-review" data-known="true">I knew it ✓</button></div><div class="review-stat">NEXT REVIEW: ${current.nextReview?fmtDate(current.nextReview):'READY NOW'} · <button class="text-button" data-action="edit-card" data-id="${current.id}">Edit card</button></div>`:`<div class="panel study-card"><span class="micro">${selected?'EMPTY DECK':'START A REVIEW'}</span><h2>${selected?'Add a card to begin.':'Create a deck to get started.'}</h2><button class="button button-dark" data-action="${selected?'new-card':'new-deck'}">＋ ${selected?'Create flashcard':'Create deck'}</button></div>`}<section class="panel" style="margin-top:18px"><div class="section-title" style="margin-top:0"><h2>Review history</h2><span class="micro">MOST RECENT FIRST</span></div>${state.reviews.length?`<table class="history-table"><thead><tr><th>Card</th><th>Result</th><th>Reviewed</th></tr></thead><tbody>${state.reviews.slice(0,8).map(r=>`<tr><td>${esc(r.front)}</td><td>${r.known?'Known':'Practice again'}</td><td>${fmtRelative(r.at)}</td></tr>`).join('')}</tbody></table>`:'<p class="fine">Review a few cards and your history will appear here.</p>'}</section></section></div>`;
 $('#studyCard')?.addEventListener('click',()=>{isFlipped=!isFlipped;renderFlashcards()});
}

function renderQuizzes(){const attempts=state.quizAttempts;app.innerHTML=shell('Check what you know, <span class="serif-accent">then keep learning.</span>','04 / Quizzes and assessments','Take an eight-question mixed assessment, optionally timed, with explanations and concept links after submission.',`<button class="button button-dark" data-action="start-quiz">Start a quiz <span>↗</span></button>`)+`<section class="grid dashboard-grid"><div class="panel shadow"><div class="eyebrow">MIXED FIRST-YEAR REVIEW</div><h2>One small check-in.</h2><p>Question types include multiple choice, true or false, fill in the blank, code output, short answer, identify the error, and matching. Your score is feedback for revision, not a gate on your progress.</p><label class="label" style="max-width:260px">TIMER<select class="field" id="quizTimer"><option value="0">No timer</option><option value="5">5 minutes</option><option value="10">10 minutes</option><option value="15">15 minutes</option></select></label><p><button class="button button-acid" data-action="start-quiz">Begin assessment <span>↗</span></button></p><div class="fine">Concept quizzes can also be launched from an individual concept page.</div></div><div class="panel"><div class="section-title" style="margin-top:0"><h2>Your results</h2><span class="micro">${attempts.length} ATTEMPTS</span></div><div class="stat-grid"><div class="stat"><strong>${attempts.length?Math.round(attempts.reduce((a,x)=>a+x.score,0)/attempts.length):'—'}</strong><span>Average score</span></div><div class="stat"><strong>${attempts.length?Math.max(...attempts.map(x=>x.score)):'—'}</strong><span>Best score</span></div></div><div class="item-list">${attempts.length?attempts.slice(0,6).map(a=>`<div class="activity"><span class="activity-mark">${a.score>=70?'✓':'↻'}</span><span>Mixed review · ${a.score}% (${a.correct}/${a.total})</span><time>${fmtRelative(a.at)}</time></div>`).join(''):'<div class="empty">Quiz attempts and scores will appear here.</div>'}</div></div></section><section class="panel" style="margin-top:16px"><div class="section-title" style="margin-top:0"><h2>Question formats</h2><span class="micro">LEARN BY RETRIEVING</span></div><div class="phase-overview">${['Multiple choice','Multiple select','True or false','Fill in the blank','Code output prediction','Code interpretation','Identify the error','Match concepts','Short answer'].map((n,i)=>`<div class="phase-mini"><span class="phase-num">${String(i+1).padStart(2,'0')}</span><strong>${n}</strong></div>`).join('')}</div><p class="fine">The current starter question bank covers several formats. More assessment content can be added through the admin editor.</p></section>`;
}

function renderProfile(){const p=state.profile,shortcuts=state.settings.shortcuts||[],s=countStats();app.innerHTML=shell('Your profile and <span class="serif-accent">workspaces.</span>','05 / Profile','Set your learning goals and keep your daily work links in one place. Your private data is stored in this browser.',`<button class="button" data-action="export-data">Export my data ↓</button><label class="button">Import data ↑<input id="importFile" type="file" accept="application/json" hidden></label><button class="button" data-action="admin">Roadmap editor ⚙</button>`)+`<div class="profile-layout"><section class="panel shadow"><div class="eyebrow">PERSONAL PROFILE</div><h2>Your learning identity</h2><form id="profileForm" class="profile-form"><label class="label">Username<input name="username" value="${esc(p.username)}" maxlength="40"></label><label class="label">Full name<input name="fullName" value="${esc(p.fullName)}" maxlength="80"></label><label class="label full">Email<input name="email" type="email" value="${esc(p.email)}" placeholder="Optional — kept on this device"></label><label class="label full">Profile picture URL<input name="picture" type="url" value="${esc(p.picture)}" placeholder="Optional image URL"></label><label class="label full">Personal learning goal<textarea name="goal" maxlength="300">${esc(p.goal)}</textarea></label><label class="label">Daily study goal (minutes)<input name="dailyGoal" type="number" min="5" max="600" value="${esc(state.settings.dailyGoal||30)}"></label><label class="label">Preferred language<select name="language"><option ${p.language==='English'?'selected':''}>English</option><option ${p.language==='Français'?'selected':''}>Français</option><option ${p.language==='العربية'?'selected':''}>العربية</option></select></label><button class="button button-acid" type="submit">Save profile</button></form><hr class="section-rule"><div class="stat-grid"><div class="stat"><strong>${s.mastered}</strong><span>Mastered</span></div><div class="stat"><strong>${s.compDone}</strong><span>Competencies</span></div><div class="stat"><strong>${state.flashcards.length}</strong><span>Flashcards</span></div><div class="stat"><strong>${state.quizAttempts.length}</strong><span>Quiz attempts</span></div></div><div class="install-banner" id="installBanner"><span>⇩</span><span><strong>Install this learning workspace.</strong> Use your browser's install option for an app-like experience.</span><button class="text-button" data-action="install">Install</button></div><p class="fine">Offline progress uses IndexedDB on this device. This standalone build does not include sign-in or cross-device synchronization.</p></section><section class="panel"><div class="eyebrow">MY WORKSPACES</div><h2>Get to your daily tools.</h2><p>Shortcuts open in a new tab. Private Jira instances are not guessable, so add the URL you received from your school or organization.</p>${shortcuts.map(s=>`<article class="workspace-card"><div class="workspace-icon">${esc(s.icon||'↗')}</div><div><h3>${esc(s.name)}</h3><p>${esc(s.description||'External workspace')} ${s.url?'<span class="micro">· LINK VERIFIED / CONFIGURED</span>':'<span class="micro">· URL NEEDED</span>'}</p></div><div class="action-row">${s.url?`<a class="link-out" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${esc(s.name)} in a new tab">↗</a>`:''}<button class="text-button" data-action="edit-shortcut" data-id="${s.id}">Edit</button></div></article>`).join('')}<div class="admin-note">Simplon Maghreb links to the public Simplon website. The YouCode intranet sign-in address was verified. Jira remains configurable because each student workspace is private.</div><hr class="section-rule"><label class="label">Theme<select class="field" id="themeSelect"><option value="light" ${state.settings.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.settings.theme==='dark'?'selected':''}>Dark</option></select></label><p><button class="text-button" data-action="clear-data">Clear this device's study data</button></p></section></div>`;
 $('#profileForm')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);state.profile.username=f.get('username').trim();state.profile.fullName=f.get('fullName').trim();state.profile.email=f.get('email').trim();state.profile.picture=f.get('picture').trim();state.profile.goal=f.get('goal').trim();state.profile.language=f.get('language');state.settings.dailyGoal=Number(f.get('dailyGoal'))||30;persist();profileTop();logActivity('Updated profile and learning goal','◉');toast('Profile saved on this device.');renderProfile()});
 $('#themeSelect')?.addEventListener('change',e=>{state.settings.theme=e.target.value;persist();profileTop()});$('#importFile')?.addEventListener('change',importData);
}

function renderAdmin(){const paths=activeCurriculum(),first=paths[0],mod=first.modules[0];app.innerHTML=shell('Manage the learning map.','06 / Local roadmap editor','Edit official phase details and module structures in this browser. Export the resulting data for review or migration.',`<button class="button" data-action="export-curriculum">Export roadmap JSON ↓</button><button class="button button-dark" data-action="profile">Back to profile</button>`)+`<section class="panel shadow"><div class="admin-note"><strong>Local editor:</strong> this standalone build has no accounts, roles, or server authorization. Changes here are device-local and do not update an official YouCode curriculum. Use the full JSON export to review a complete phase structure.</div><form id="adminForm" class="dialog-form" style="margin-top:18px"><label class="label full">Phase<select name="phase" class="field">${paths.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></label><label class="label">Phase title<input name="title" value="${esc(first.title)}" required></label><label class="label">Estimated duration<input name="duration" value="${esc(first.duration)}"></label><label class="label full">Overview<textarea name="overview">${esc(first.overview)}</textarea></label><label class="label full">Module<select name="module" class="field">${first.modules.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><label class="label">Module name<input name="moduleName" value="${esc(mod.name)}"></label><label class="label">Module duration<input name="moduleDuration" value="${esc(mod.duration)}"></label><label class="label full">Topics, one concept per line<textarea name="topics" rows="10">${mod.concepts.map(c=>esc(c.title)).join('\n')}</textarea></label><button class="button button-acid" type="submit">Save phase and module</button><button class="button" type="button" data-action="reset-curriculum">Reset local roadmap edits</button></form></section>`;
 const form=$('#adminForm');function updateFields(){const p=paths.find(x=>x.id===form.phase.value)||paths[0],m=p.modules.find(x=>x.id===form.module.value)||p.modules[0];form.title.value=p.title;form.duration.value=p.duration;form.overview.value=p.overview;form.module.innerHTML=p.modules.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');form.module.value=m.id;form.moduleName.value=m.name;form.moduleDuration.value=m.duration;form.topics.value=m.concepts.map(c=>c.title).join('\n')}
 form.phase.addEventListener('change',updateFields);form.module.addEventListener('change',updateFields);form.addEventListener('submit',e=>{e.preventDefault();const p=paths.find(x=>x.id===form.phase.value),m=p.modules.find(x=>x.id===form.module.value);p.title=form.title.value.trim();p.duration=form.duration.value.trim();p.overview=form.overview.value.trim();m.name=form.moduleName.value.trim();m.duration=form.moduleDuration.value.trim();const topicNames=[...new Set(form.topics.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean))];m.concepts=topicNames.map((title,i)=>m.concepts.find(c=>c.title.toLowerCase()===title.toLowerCase())||{id:`${p.id}-${m.id}-${i}-${title.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`,title,phaseIndex:p.index,moduleIndex:p.modules.indexOf(m),supplementary:!!m.supplementary,explanation:`${title} is part of ${m.name}. Explore its purpose, prerequisites, and use in a small application.`,exercise:`Create and explain a small example of ${title.toLowerCase()}.`,competencies:[`Explain the purpose of ${title.toLowerCase()}.`,`Use ${title.toLowerCase()} in an example.`,`Find and fix a common mistake.`,`Apply ${title.toLowerCase()} in a small project.`],resources:[],checklistLabels:['I understand the theory','I can explain the concept','I can write the code independently','I can debug related errors','I can apply it in a project']});state.admin={...state.admin,phases:paths.map(x=>JSON.parse(JSON.stringify(x)))};persist();logActivity(`Edited ${p.title} in the local roadmap editor`,'⚙');toast('Roadmap changes saved on this device.');renderAdmin()});
}

function render(){profileTop();switch(route){case'welcome':renderWelcome();break;case'home':renderHome();break;case'roadmap':renderRoadmap();break;case'tasks':renderTasks();break;case'flashcards':renderFlashcards();break;case'quizzes':renderQuizzes();break;case'profile':renderProfile();break;case'admin':renderAdmin();break;case'quiz-run':renderQuizRun();break;default:route='home';renderHome()}if(route!=='welcome'){const wrap=app.querySelector('.app-shell');if(wrap)for(const node of [...app.childNodes])if(node!==wrap)wrap.appendChild(node)}initMotion()}

let revealObserver=null,parallaxQueued=false,parallaxBound=false;
function initMotion(){
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 document.body.classList.toggle('motion-ready',!reduced);
 document.body.classList.toggle('motion-reduced',reduced);
 const targets=$$('[data-reveal],.page-heading,.hero-panel,.panel',app);
 if(!reduced&&'IntersectionObserver'in window){revealObserver?.disconnect();revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}}),{threshold:.08,rootMargin:'0px 0px -24px 0px'});targets.forEach(el=>{el.classList.add('reveal-item');revealObserver.observe(el)})}else targets.forEach(el=>el.classList.add('is-visible'));
 if(!parallaxBound){window.addEventListener('scroll',queueParallax,{passive:true});window.addEventListener('resize',queueParallax,{passive:true});parallaxBound=true}
 queueParallax();
}
function queueParallax(){if(parallaxQueued)return;parallaxQueued=true;requestAnimationFrame(()=>{parallaxQueued=false;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches,small=window.innerWidth<=700;$$('[data-parallax-speed]').forEach(el=>{if(reduced||small){el.style.setProperty('--parallax-y','0px');return}const r=el.getBoundingClientRect(),center=r.top+r.height/2,offset=Math.max(-220,Math.min(220,(window.innerHeight/2-center)*Number(el.dataset.parallaxSpeed||0)));el.style.setProperty('--parallax-y',`${offset}px`)})})}

function dialogOpen(html,heading){dialog.classList.remove('wide');dialogContent.innerHTML=heading?`<div class="eyebrow">${esc(heading)}</div>${html}`:html;dialog.showModal()}
function label(name,title,type='text',value='',extra=''){return `<label class="label ${extra.includes('full')?'full':''}">${esc(title)}${type==='textarea'?`<textarea name="${name}" ${extra}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}</label>`}
function taskDialog(existing){const t=existing||{};dialogOpen(`<h2>${t.id?'Edit':'Add'} a learning task.</h2><form class="dialog-form" data-form="task" data-id="${t.id||''}">${label('title','Title','text',t.title||'','required maxlength="120" class="full"')}${label('description','Description and notes','textarea',t.description||'','maxlength="800" class="full"')}<label class="label">Category<select name="category" class="field"><option ${t.category==='Practice'?'selected':''}>Practice</option><option ${t.category==='Project'?'selected':''}>Project</option><option ${t.category==='Course'?'selected':''}>Course</option><option ${t.category==='Personal'?'selected':''}>Personal</option></select></label><label class="label">Priority<select name="priority" class="field"><option value="low" ${t.priority==='low'?'selected':''}>Low</option><option value="normal" ${!t.priority||t.priority==='normal'?'selected':''}>Normal</option><option value="high" ${t.priority==='high'?'selected':''}>High</option></select></label><label class="label">Difficulty<select name="difficulty" class="field"><option>Beginner</option><option ${t.difficulty==='Intermediate'?'selected':''}>Intermediate</option><option ${t.difficulty==='Advanced'?'selected':''}>Advanced</option></select></label>${label('dueDate','Due date','date',t.dueDate||'')}${label('estimatedMinutes','Estimated duration (minutes)','number',t.estimatedMinutes||30,'min="5" max="5000"')}${label('resources','Resources (one URL per line)','textarea',(t.resources||[]).join('\n'),'class="full"')}<label class="label full">Related concept (optional)<select name="conceptId" class="field"><option value="">Independent task</option>${currentConcepts().map(c=>`<option value="${c.id}" ${t.conceptId===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><label class="label full">Status<select name="status" class="field"><option value="todo" ${!t.status||t.status==='todo'?'selected':''}>Not started</option><option value="in-progress" ${t.status==='in-progress'?'selected':''}>In progress</option><option value="done" ${t.status==='done'?'selected':''}>Done</option></select></label><div class="action-row label full"><button class="button button-dark" type="submit">Save task</button><button class="button" type="button" data-action="close-dialog">Cancel</button></div></form>`,'PERSONAL LEARNING TASK')}
function deckDialog(){dialogOpen(`<h2>Create a flashcard deck.</h2><form class="dialog-form" data-form="deck">${label('name','Deck name','text','','required maxlength="80" class="full"')}${label('description','Short description','textarea','','maxlength="240" class="full"')}<label class="label full">Associate with<select name="phaseId" class="field"><option value="">Personal deck</option>${activeCurriculum().map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></label><div class="action-row label full"><button class="button button-dark" type="submit">Create deck</button></div></form>`,'FLASHCARDS')}
function cardDialog(existing){const c=existing||{};const decks=state.decks;dialogOpen(`<h2>${c.id?'Edit your card.':'Create a flashcard.'}</h2>${!decks.length?'<p class="admin-note">Create a deck before saving a flashcard.</p>':''}<form class="dialog-form" data-form="card" data-id="${c.id||''}">${label('front','Question / front','textarea',c.front||'','required maxlength="500" class="full"')}${label('back','Answer / back','textarea',c.back||'','required maxlength="1000" class="full"')}${label('code','Optional code example','textarea',c.code||'','maxlength="1200" class="full"')}<label class="label full">Deck<select name="deckId" class="field" required>${decks.map(d=>`<option value="${d.id}" ${c.deckId===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><label class="label full">Associated concept<select name="conceptId" class="field"><option value="">Personal card</option>${currentConcepts().map(x=>`<option value="${x.id}" ${c.conceptId===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label>${label('tags','Tags (comma separated)','text',(c.tags||[]).join(', '),'class="full"')}${label('imageUrl','Optional image URL','url',c.image||'','class="full"')}<label class="label full">Or attach an image<input type="file" name="imageFile" accept="image/*"></label><div class="action-row label full"><button class="button button-dark" type="submit" ${!decks.length?'disabled':''}>Save flashcard</button><button class="button" type="button" data-action="close-dialog">Cancel</button></div><p class="fine label full">Cards are stored on this device. AI drafting is available only after a secure provider integration is configured; no API key is stored in this browser.</p></form>`,'FLASHCARDS')}
function resourceDialog(concept,resource){dialogOpen(`<h2>${resource?'Edit':'Add'} a personal reference.</h2><form class="dialog-form" data-form="resource" data-id="${resource?.id||''}" data-concept="${concept.id}">${label('title','Resource title','text',resource?.title||'','required maxlength="120" class="full"')}${label('url','URL','url',resource?.url||'','required class="full"')}<label class="label">Resource type<select name="type" class="field">${['Official documentation','Tutorial','Video','Interactive exercise','Article','Practice platform','Reference guide'].map(x=>`<option ${resource?.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="label">Language<select name="language" class="field"><option>English</option><option>Français</option><option>العربية</option><option>Other</option></select></label>${label('description','Description','textarea',resource?.description||'','maxlength="300" class="full"')}<div class="action-row label full"><button class="button button-dark" type="submit">Save reference</button></div><p class="fine label full">Personal references remain separate from recommended learning resources. Check a link before saving it.</p></form>`,'PERSONAL RESOURCE')}
function conceptDialogLegacy(id){const c=findConcept(id)||currentConcepts().find(x=>x.id===id);if(!c)return;selectedConceptId=id;const p=activeCurriculum()[c.phaseIndex],m=p?.modules[c.moduleIndex],comps=state.competencyProgress[id]||[],checks=state.mastery[id]||[],personal=state.userResources[id]||[];const phaseResources=c.resources.map(r=>`<article class="resource"><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a><small>${esc(r.source)} · ${esc(r.type)} · ${esc(r.language)} · Verified ${new Date().toISOString().slice(0,10)}</small><p>${esc(r.description)}</p></article>`).join('');const custom=personal.map(r=>`<article class="resource"><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a><small>YOUR LINK · ${esc(r.type)}</small><p>${esc(r.description||'')}</p><div class="resource-actions"><button class="text-button" data-action="edit-resource" data-id="${r.id}" data-concept="${id}">Edit</button><button class="text-button" data-action="delete-resource" data-id="${r.id}" data-concept="${id}">Delete</button></div></article>`).join('');
 dialogOpen(`<div class="concept-heading"><span class="tag">PHASE ${String(c.phaseIndex+1).padStart(2,'0')} · ${c.supplementary?'SUPPLEMENTARY':'RECOMMENDED DETAIL'}</span><h2>${esc(c.title)}</h2><p>${esc(p?.title||'')} / ${esc(m?.name||'')}</p></div><div class="grid" style="grid-template-columns:1fr 1fr;gap:14px"><section><div class="micro">CONCEPT</div><p>${esc(c.explanation)}</p><div class="micro">TRY IT</div><p>${esc(c.exercise)}</p><div class="micro">REQUIRED COMPETENCIES</div><ul class="competency-list">${c.competencies.map((x,i)=>`<li><input type="checkbox" data-competency="${id}" data-index="${i}" ${comps[i]?'checked':''} aria-label="Mark competency complete: ${esc(x)}"><span>${esc(x)}</span></li>`).join('')}</ul></section><section><div class="micro">YOUR LEARNING STATUS</div><select id="conceptStatus" class="status-select" data-concept-status="${id}"><option value="not-started" ${status(id)==='not-started'?'selected':''}>○ Not started</option><option value="learning" ${status(id)==='learning'?'selected':''}>◉ Learning</option><option value="mastered" ${status(id)==='mastered'?'selected':''}>✓ Mastered</option></select><div class="micro">MASTERY REFLECTION</div><ul class="checklist">${c.checklistLabels.map((x,i)=>`<li class="check-row"><input type="checkbox" data-mastery="${id}" data-index="${i}" ${checks[i]?'checked':''}><span>${esc(x)}</span></li>`).join('')}</ul><p class="fine">Choose Mastered when you are ready. This is self-reported; quizzes can help you check but do not block your choice.</p><div class="action-row"><button class="button button-dark" data-action="concept-quiz" data-id="${id}">Quiz this concept</button><button class="button button-acid" data-action="card-from-concept" data-id="${id}">＋ Flashcard</button></div></section></div><hr class="section-rule"><div class="section-title" style="margin-top:0"><h3>Recommended resources</h3><span class="tag">CURATED</span></div><div class="resource-list">${phaseResources||'<div class="empty">No starter references for this concept yet.</div>'}</div><div class="section-title"><h3>Your references</h3><button class="button button-small" data-action="new-resource" data-concept="${id}">＋ Add link</button></div><div class="resource-list">${custom||'<p class="fine">Your links are personal and cannot replace the shared recommended references.</p>'}</div><p class="fine">Resource titles, URLs and source are shown separately. Check links with their publisher before relying on them.</p>`,'CONCEPT DETAIL');
}

function conceptDialog(id){
 const c=findConcept(id);if(!c)return;selectedConceptId=id;logActivity(`Opened concept: ${c.title}`,'↗',id);const p=activeCurriculum()[c.phaseIndex],m=p?.modules[c.moduleIndex],comps=state.competencyProgress[id]||[],checks=state.mastery[id]||[],personal=state.userResources[id]||[];
 const resources=(c.resources||[]).map(r=>`<article class="resource"><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a><small>${esc(r.source)} · ${esc(r.type)} · ${esc(r.language)} · Checked ${esc(r.lastVerified||OFFICIAL_PROGRAMME.verifiedDate)}</small><p>${esc(r.description)}</p></article>`).join('');
 const custom=personal.map(r=>`<article class="resource personal-resource"><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a><small>YOUR REFERENCE · ${esc(r.type)}</small><p>${esc(r.description||'')}</p><div class="resource-actions"><button class="text-button" data-action="edit-resource" data-id="${r.id}" data-concept="${id}">Edit</button><button class="text-button" data-action="delete-resource" data-id="${r.id}" data-concept="${id}">Delete</button></div></article>`).join('');
 const related=(c.relatedConcepts||[]).map(title=>{const match=currentConcepts().find(x=>x.title===title);return match?`<button class="related-chip" data-action="concept" data-id="${match.id}">${esc(title)} ↗</button>`:`<span class="related-chip">${esc(title)}</span>`}).join('');
 dialogOpen(`<div class="concept-topline"><span class="tag">EXTENDED DEVELOPER ROADMAP</span><span class="source-stamp">RECOMMENDED · NOT OFFICIAL MODULE DETAIL</span></div><header class="concept-title"><div class="micro">YEAR 1 / PHASE ${String(c.phaseIndex+1).padStart(2,'0')} / ${esc(m?.name||'')}</div><h2>${esc(c.title)}</h2><p>${esc(p?.title||'')}</p></header><div class="concept-layout"><article class="concept-reading"><section class="concept-section"><div class="micro">DEFINITION</div><p class="concept-definition">${esc(c.definition)}</p><div class="micro">EXPLANATION</div><p>${esc(c.explanation)}</p><div class="micro">WHY IT MATTERS</div><p>${esc(c.whyItMatters)}</p></section>${c.codeExample?`<section class="concept-section"><div class="micro">CODE EXAMPLE</div><pre class="code-block"><code>${esc(c.codeExample)}</code></pre></section>`:''}<section class="concept-section"><div class="micro">LEARNING OBJECTIVES</div><ul>${(c.objectives||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="micro">PREREQUISITES</div><p>${(c.prerequisites||[]).length?c.prerequisites.map(esc).join(' · '):'No earlier concept listed.'}</p></section><section class="concept-section"><div class="micro">ESSENTIAL TERMINOLOGY</div><dl class="term-list">${(c.terminology||[]).map(x=>`<dt>${esc(x.term)}</dt><dd>${esc(x.definition)}</dd>`).join('')}</dl></section><section class="concept-section"><div class="micro">COMMON MISTAKES / CHECKS</div><ul>${(c.commonMistakes||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="concept-section exercise-box"><div class="micro">PRACTICAL EXERCISE</div><p>${esc(c.exercise)}</p></section><section class="concept-section"><div class="micro">RELATED CONCEPTS</div><div class="related-list">${related}</div></section></article><aside class="concept-study"><section class="concept-section"><div class="micro">YOUR LEARNING STATUS</div><select id="conceptStatus" class="status-select" data-concept-status="${id}"><option value="not-started" ${status(id)==='not-started'?'selected':''}>○ Not started</option><option value="learning" ${status(id)==='learning'?'selected':''}>◉ Learning</option><option value="mastered" ${status(id)==='mastered'?'selected':''}>✓ Mastered</option></select><p class="fine">Choose Mastered when you can do the work. Self-reported mastery does not require a quiz.</p></section><section class="concept-section"><div class="micro">OBSERVABLE COMPETENCIES</div><ul class="competency-list">${c.competencies.map((x,i)=>`<li><input type="checkbox" data-competency="${id}" data-index="${i}" ${comps[i]?'checked':''} aria-label="Mark competency complete: ${esc(x)}"><span>${esc(x)}</span></li>`).join('')}</ul><div class="completion-count">${comps.filter(Boolean).length} / ${c.competencies.length} competencies checked</div></section><section class="concept-section"><div class="micro">MASTERY REFLECTION</div><ul class="checklist">${c.checklistLabels.map((x,i)=>`<li class="check-row"><input type="checkbox" data-mastery="${id}" data-index="${i}" ${checks[i]?'checked':''}><span>${esc(x)}</span></li>`).join('')}</ul></section><div class="action-column"><button class="button button-dark" data-action="concept-quiz" data-id="${id}">Quiz this concept <span>↗</span></button><button class="button button-acid" data-action="card-from-concept" data-id="${id}">＋ Create a flashcard</button></div><p class="fine">Concept content is a learning aid. Compare it with the linked publisher documentation and your instructor's materials.</p></aside></div><hr class="section-rule"><div class="section-title"><h3>Recommended resources</h3><span class="tag">PUBLISHER LINKS</span></div><div class="resource-list resource-grid">${resources||'<div class="empty">No reference added yet.</div>'}</div><div class="section-title"><h3>Your references</h3><button class="button button-small" data-action="new-resource" data-concept="${id}">＋ Add link</button></div><div class="resource-list resource-grid">${custom||'<p class="fine">Your links are stored separately and cannot overwrite recommended references.</p>'}</div>`,'CONCEPT STUDY');dialog.classList.add('wide');
}

function renderQuizRun(){if(!activeQuiz){route='quizzes';renderQuizzes();return}const q=activeQuiz.questions[activeQuiz.index],answer=activeQuiz.answers[q.id],options=q.options||[];clearInterval(quizTimer);if(activeQuiz.timeLeft>0)quizTimer=setInterval(()=>{activeQuiz.timeLeft--;if(activeQuiz.timeLeft<=0){clearInterval(quizTimer);finishQuiz()}else{const t=$('#quizClock');if(t)t.textContent=`${Math.floor(activeQuiz.timeLeft/60)}:${String(activeQuiz.timeLeft%60).padStart(2,'0')}`}},1000);
 let input='';if(options.length){input=`<div class="quiz-options">${options.map((o,i)=>`<button type="button" class="quiz-option ${answer===i?'selected':''}" data-action="quiz-answer" data-value="${i}"><span>${String.fromCharCode(65+i)}.</span><span>${esc(o)}</span></button>`).join('')}</div>`}else if(q.type==='true-false'){input=`<div class="quiz-options">${['True','False'].map((o,i)=>`<button type="button" class="quiz-option ${answer===(i===0)?'selected':''}" data-action="quiz-answer" data-value="${i===0}">${o}</button>`).join('')}</div>`}else if(q.type==='match'){input=`<label class="label">Your match<textarea class="field" id="quizTextAnswer" rows="3" placeholder="Write each term and its role">${esc(answer||'')}</textarea></label>`}else input=`<label class="label">Your answer<textarea class="field" id="quizTextAnswer" rows="3" placeholder="Type your answer">${esc(answer||'')}</textarea></label>`;
 const evaluated=activeQuiz.submitted?checkAnswer(q,answer):null;app.innerHTML=`<div class="app-shell quiz-stage"><div class="page-heading"><div><div class="eyebrow">ASSESSMENT / ${activeQuiz.index+1} OF ${activeQuiz.questions.length}</div><h1>${activeQuiz.conceptId?esc(findConcept(activeQuiz.conceptId)?.title||'Concept review'):'Mixed first-year review'}</h1></div><div class="action-row"><span class="tag" id="quizClock">${activeQuiz.timeLeft?`${Math.floor(activeQuiz.timeLeft/60)}:${String(activeQuiz.timeLeft%60).padStart(2,'0')}`:'NO TIMER'}</span><button class="button" data-action="exit-quiz">Exit quiz</button></div></div><div class="progress-track"><i style="width:${pct(activeQuiz.index+1,activeQuiz.questions.length)}%"></i></div><section class="panel shadow"><div class="micro">${esc(q.type.replaceAll('-',' ').toUpperCase())} · QUESTION ${activeQuiz.index+1}</div><h2 class="quiz-question">${esc(q.question)}</h2>${input}${evaluated!==null?`<div class="quiz-feedback"><strong>${evaluated?'Correct.':'Review this one.'}</strong> ${esc(q.explanation)}<br><span class="micro">RELATED CONCEPT: ${esc(q.related)}</span></div>`:''}<div class="action-row" style="justify-content:space-between;margin-top:20px"><button class="button" data-action="quiz-prev" ${activeQuiz.index===0?'disabled':''}>← Previous</button><span class="micro">${Object.keys(activeQuiz.answers).length} ANSWERED</span>${activeQuiz.index<activeQuiz.questions.length-1?`<button class="button button-dark" data-action="quiz-next">Next →</button>`:`<button class="button button-acid" data-action="quiz-submit">Submit assessment ✓</button>`}</div></section><nav class="action-row" style="justify-content:center;margin-top:14px">${activeQuiz.questions.map((x,i)=>`<button class="button button-small ${i===activeQuiz.index?'button-blue':''}" data-action="quiz-goto" data-index="${i}" aria-label="Go to question ${i+1}">${i+1}</button>`).join('')}</nav></div>`;
}
function checkAnswer(q,value){if(value===undefined||value===null||value==='')return false;if(q.options)return value===q.answer;if(q.type==='true-false')return value===q.answer;const norm=x=>String(x).toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();if(q.type==='identify-error')return norm(value).includes('semicolon')||norm(value).includes('semicolon missing')||norm(value).includes('missing a semicolon');if(q.type==='match')return norm(value).includes('primary key')&&norm(value).includes('foreign key');const expected=norm(q.answerText);const actual=norm(value);if(q.type==='short-answer')return ['bubble','ancestor','parent'].every(x=>actual.includes(x));return actual===expected||actual.includes(expected)}
function startQuiz(conceptId=null){let questions=QUIZ_BANK;if(conceptId){const concept=findConcept(conceptId)||currentConcepts().find(c=>c.id===conceptId);questions=QUIZ_BANK.filter(q=>q.related.toLowerCase()===(concept?.title||'').toLowerCase());if(!questions.length)questions=QUIZ_BANK.filter(q=>q.related.toLowerCase().includes((concept?.title||'!').toLowerCase().split(' ')[0]));if(!questions.length){toast('No question has been added for this concept yet. Try the mixed assessment.');return}}
 else questions=[...QUIZ_BANK];const timerMinutes=Number($('#quizTimer')?.value||0);activeQuiz={questions:questions.map(q=>({...q})),index:0,answers:{},submitted:false,conceptId,timeLeft:timerMinutes*60,startedAt:new Date().toISOString()};route='quiz-run';history.replaceState(null,'','#quiz-run');render()}
function finishQuiz(){if(!activeQuiz||activeQuiz.submitted)return;clearInterval(quizTimer);activeQuiz.submitted=true;const correct=activeQuiz.questions.filter(q=>checkAnswer(q,activeQuiz.answers[q.id])).length;const attempt={id:uid(),score:pct(correct,activeQuiz.questions.length),correct,total:activeQuiz.questions.length,at:new Date().toISOString(),answers:activeQuiz.answers,questions:activeQuiz.questions.map(q=>q.id)};state.quizAttempts.unshift(attempt);persist();logActivity(`Completed a quiz with ${attempt.score}%`,'▣');app.innerHTML=`<div class="app-shell quiz-stage"><div class="page-heading"><div><div class="eyebrow">ASSESSMENT / COMPLETE</div><h1>Your result.</h1></div></div><section class="panel shadow quiz-result"><div class="eyebrow">${attempt.score>=70?'SOLID RECALL':'GOOD REVISION SIGNAL'}</div><strong>${attempt.score}%</strong><p>${attempt.correct} correct out of ${attempt.total}. Use the explanations to choose your next revision topic.</p><div class="progress-track"><i style="width:${attempt.score}%"></i></div><div class="action-row" style="justify-content:center"><button class="button button-dark" data-action="quiz-review">Review answers</button><button class="button button-acid" data-action="retake-quiz">Retake quiz</button><button class="button" data-action="quiz-home">Quiz history</button></div></section><section id="quizReview" class="panel" style="margin-top:15px"><div class="section-title" style="margin-top:0"><h2>Answer review</h2></div>${activeQuiz.questions.map(q=>{const ok=checkAnswer(q,activeQuiz.answers[q.id]);return `<article class="activity"><span class="activity-mark">${ok?'✓':'↻'}</span><div><strong>${esc(q.question)}</strong><p>Your answer: ${esc(answerText(q,activeQuiz.answers[q.id]))}</p><p>${esc(q.explanation)}</p><span class="tag">REVISE: ${esc(q.related)}</span></div></article>`}).join('')}</section></div>`}
function answerText(q,value){if(value===undefined)return 'Not answered';if(q.options)return q.options[value]||'Not answered';if(q.type==='true-false')return value?'True':'False';return String(value)}

function editShortcutDialog(id){const s=state.settings.shortcuts.find(x=>x.id===id);if(!s)return;dialogOpen(`<h2>Edit ${esc(s.name)} shortcut.</h2><form class="dialog-form" data-form="shortcut" data-id="${s.id}">${label('name','Name','text',s.name,'required maxlength="80" class="full"')}${label('url','Destination URL','url',s.url,'class="full"')}${label('description','Description','textarea',s.description||'','maxlength="240" class="full"')}<div class="action-row label full"><button class="button button-dark" type="submit">Save shortcut</button></div><p class="fine label full">Only add workspace destinations you received from your organization. This app never asks for workspace credentials.</p></form>`,'WORKSPACE SHORTCUT')}

function saveTask(form,id){const f=new FormData(form),existing=state.tasks.find(t=>t.id===id),task={id:id||uid(),title:String(f.get('title')).trim(),description:String(f.get('description')).trim(),category:f.get('category'),priority:f.get('priority'),difficulty:f.get('difficulty'),dueDate:f.get('dueDate'),estimatedMinutes:Number(f.get('estimatedMinutes'))||0,status:f.get('status'),resources:String(f.get('resources')).split(/\r?\n/).map(x=>x.trim()).filter(Boolean),conceptId:f.get('conceptId')||'',notes:existing?.notes||'',createdAt:existing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(existing)Object.assign(existing,task);else state.tasks.unshift(task);persist();logActivity(`${existing?'Updated':'Created'} task: ${task.title}`,'✓');dialog.close();route='tasks';render();toast('Task saved.')}
async function saveCard(form,id){const f=new FormData(form),existing=state.flashcards.find(c=>c.id===id);let image=String(f.get('imageUrl')||'').trim(),file=form.querySelector('[name=imageFile]').files[0];if(file)image=await new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>resolve('');reader.readAsDataURL(file)});const card={id:id||uid(),front:String(f.get('front')).trim(),back:String(f.get('back')).trim(),code:String(f.get('code')).trim(),deckId:f.get('deckId'),conceptId:f.get('conceptId')||'',tags:String(f.get('tags')).split(',').map(x=>x.trim()).filter(Boolean),image,intervalDays:existing?.intervalDays||0,ease:existing?.ease||2.5,repetitions:existing?.repetitions||0,nextReview:existing?.nextReview||'',known:existing?.known||false,createdAt:existing?.createdAt||new Date().toISOString()};if(existing)Object.assign(existing,card);else state.flashcards.unshift(card);persist();logActivity(`${existing?'Edited':'Created'} flashcard: ${card.front.slice(0,50)}`,'▤');dialog.close();route='flashcards';selectedDeckId=card.deckId;reviewIndex=0;isFlipped=false;render();toast('Flashcard saved.')}
function reviewCard(card,known){const now=new Date(),r=state.reviews;if(known){card.repetitions=(card.repetitions||0)+1;card.intervalDays=card.repetitions===1?1:card.repetitions===2?3:Math.max(4,Math.round((card.intervalDays||3)*(card.ease||2.5)));card.ease=Math.max(1.3,(card.ease||2.5)+0.1)}else{card.repetitions=0;card.intervalDays=0;card.ease=Math.max(1.3,(card.ease||2.5)-0.2)}card.known=known;card.nextReview=new Date(now.getTime()+card.intervalDays*86400000).toISOString();state.reviews.unshift({id:uid(),cardId:card.id,front:card.front,known,at:now.toISOString()});state.reviews=state.reviews.slice(0,500);persist();logActivity(`${known?'Knew':'Practiced'} a flashcard: ${card.front.slice(0,45)}`,known?'✓':'↻');isFlipped=false;const q=dueCards(state.flashcards.filter(c=>c.deckId===selectedDeckId));reviewIndex=Math.min(reviewIndex,q.length-1);renderFlashcards()}

function editResource(conceptId,id){const r=(state.userResources[conceptId]||[]).find(x=>x.id===id);resourceDialog(findConcept(conceptId)||currentConcepts().find(c=>c.id===conceptId),r)}
function deleteResource(conceptId,id){state.userResources[conceptId]=(state.userResources[conceptId]||[]).filter(r=>r.id!==id);persist();conceptDialog(conceptId);toast('Personal reference deleted.')}

function importData(e){const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const imported=JSON.parse(reader.result);if(!imported||typeof imported!=='object'||!imported.profile||!imported.progress)throw new Error('This file does not look like a Learn workspace export.');state={...state,...imported,settings:{...state.settings,...imported.settings},profile:{...state.profile,...imported.profile}};persist();profileTop();toast('Workspace data imported.');renderProfile()}catch(err){toast(`Import failed: ${err.message}`)}};reader.readAsText(file)}
function downloadJson(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;
 if(action==='roadmap-track'){roadmapTrack=id==='official'?'official':'extended';roadmapQuery='';if(route==='roadmap')renderRoadmap();else setRoute('roadmap');return}
 if(action==='jump-phase'){roadmapTrack=roadmapTrack||'extended';if(route!=='roadmap')setRoute('roadmap');else renderRoadmap();requestAnimationFrame(()=>{const d=document.getElementById(roadmapTrack==='official'?id.replace('phase-','phase-'):id);if(d){d.open=true;d.scrollIntoView({behavior:'smooth',block:'start'})}});return}
 if(action==='open-phase'){e.preventDefault();setRoute('roadmap');setTimeout(()=>{const d=$(`#${CSS.escape(id)}`);if(d){d.open=true;d.scrollIntoView({behavior:'smooth',block:'start'})}},40)}
 else if(action==='concept')conceptDialog(id);
 else if(action==='new-task')taskDialog();else if(action==='edit-task')taskDialog(state.tasks.find(t=>t.id===id));else if(action==='delete-task'){if(confirm('Delete this personal learning task?')){state.tasks=state.tasks.filter(t=>t.id!==id);persist();logActivity('Deleted a personal task','×');renderTasks()}}
 else if(action==='new-deck')deckDialog();else if(action==='select-deck'){selectedDeckId=id;reviewIndex=0;isFlipped=false;renderFlashcards()}else if(action==='new-card'){if(!state.decks.length){toast('Create a deck before creating a card.');deckDialog()}else cardDialog()}else if(action==='edit-card')cardDialog(state.flashcards.find(c=>c.id===id));else if(action==='card-prev'){const c=state.flashcards.filter(x=>x.deckId===selectedDeckId);reviewIndex=(reviewIndex-1+c.length)%c.length;isFlipped=false;renderFlashcards()}else if(action==='card-next'){const c=state.flashcards.filter(x=>x.deckId===selectedDeckId);reviewIndex=(reviewIndex+1)%c.length;isFlipped=false;renderFlashcards()}else if(action==='card-shuffle'){reviewQueue=dueCards(state.flashcards.filter(x=>x.deckId===selectedDeckId)).sort(()=>Math.random()-.5);const ids=reviewQueue.map(x=>x.id);const deck=state.flashcards.filter(x=>x.deckId===selectedDeckId);state.flashcards=state.flashcards.filter(x=>x.deckId!==selectedDeckId).concat(ids.map(x=>deck.find(y=>y.id===x)));reviewIndex=0;renderFlashcards()}else if(action==='card-review'){const card=dueCards(state.flashcards.filter(x=>x.deckId===selectedDeckId))[reviewIndex];if(card)reviewCard(card,b.dataset.known==='true')}
 else if(action==='start-quiz')startQuiz();else if(action==='concept-quiz')startQuiz(id);else if(action==='quiz-answer'){const q=activeQuiz.questions[activeQuiz.index];if(q.options)activeQuiz.answers[q.id]=Number(b.dataset.value);else activeQuiz.answers[q.id]=b.dataset.value==='true';renderQuizRun()}else if(action==='quiz-next'){const q=activeQuiz.questions[activeQuiz.index];const text=$('#quizTextAnswer');if(text)activeQuiz.answers[q.id]=text.value;activeQuiz.index=Math.min(activeQuiz.index+1,activeQuiz.questions.length-1);renderQuizRun()}else if(action==='quiz-prev'){const q=activeQuiz.questions[activeQuiz.index],text=$('#quizTextAnswer');if(text)activeQuiz.answers[q.id]=text.value;activeQuiz.index=Math.max(0,activeQuiz.index-1);renderQuizRun()}else if(action==='quiz-goto'){const q=activeQuiz.questions[activeQuiz.index],text=$('#quizTextAnswer');if(text)activeQuiz.answers[q.id]=text.value;activeQuiz.index=Number(b.dataset.index);renderQuizRun()}else if(action==='quiz-submit'){const q=activeQuiz.questions[activeQuiz.index],text=$('#quizTextAnswer');if(text)activeQuiz.answers[q.id]=text.value;finishQuiz()}else if(action==='exit-quiz'){clearInterval(quizTimer);activeQuiz=null;route='quizzes';render()}else if(action==='quiz-home'){activeQuiz=null;route='quizzes';render()}else if(action==='quiz-review')$('#quizReview')?.scrollIntoView({behavior:'smooth'});else if(action==='retake-quiz'){activeQuiz=null;startQuiz()}
 else if(action==='new-resource'){const c=findConcept(b.dataset.concept)||currentConcepts().find(x=>x.id===b.dataset.concept);resourceDialog(c)}else if(action==='edit-resource')editResource(b.dataset.concept,id);else if(action==='delete-resource')deleteResource(b.dataset.concept,id);else if(action==='card-from-concept'){const c=findConcept(id);if(!state.decks.length){toast('Create a deck, then add a card for this concept.');deckDialog()}else cardDialog({conceptId:id,front:`What do you know about ${c?.title}?`,back:c?.explanation,deckId:selectedDeckId||state.decks[0].id})}
 else if(action==='edit-shortcut')editShortcutDialog(id);else if(action==='admin'){setRoute('admin')}else if(action==='profile')setRoute('profile');else if(action==='export-data')downloadJson('youlearn-workspace.json',state);else if(action==='export-curriculum')downloadJson('youlearn-roadmap.json',activeCurriculum());else if(action==='reset-curriculum'){if(confirm('Reset roadmap edits stored on this device?')){state.admin={};curriculum=structuredClone(CURRICULUM);persist();renderAdmin();toast('Local roadmap edits reset.')}}else if(action==='clear-data'){if(confirm('Clear all learning progress, cards, tasks, and profile settings from this device?')){indexedDB.deleteDatabase('youlearn-study-workspace');localStorage.removeItem('youlearn-study-workspace-v1');location.reload()}}
 else if(action==='install'){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.then(()=>installPrompt=null)}else toast('Use your browser menu and choose Install app or Add to Home Screen.')}else if(action==='close-dialog')dialog.close();
});

document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-competency]')){const id=t.dataset.competency,i=Number(t.dataset.index);state.competencyProgress[id]=state.competencyProgress[id]||[];state.competencyProgress[id][i]=t.checked;persist();logActivity(`${t.checked?'Checked':'Reopened'} a competency`,'✓')}else if(t.matches('[data-mastery]')){const id=t.dataset.mastery,i=Number(t.dataset.index);state.mastery[id]=state.mastery[id]||[];state.mastery[id][i]=t.checked;persist()}else if(t.matches('[data-concept-status]')){state.progress[t.dataset.conceptStatus]=t.value;persist();logActivity(`Set ${findConcept(t.dataset.conceptStatus)?.title||'a concept'} to ${statusLabel(t.value)}`,'◉');toast(`Status updated: ${statusLabel(t.value)}.`)}else if(t.matches('[data-task-status]')){const task=state.tasks.find(x=>x.id===t.dataset.taskStatus);if(task){task.status=t.value;task.updatedAt=new Date().toISOString();persist();logActivity(`Updated task status: ${task.title}`,'✓');renderTasks()}}});

dialogContent.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(!f.matches('[data-form]'))return;const formKind=f.dataset.form,id=f.dataset.id;
 if(formKind==='task')saveTask(f,id);else if(formKind==='deck'){const d={id:uid(),name:new FormData(f).get('name').trim(),description:new FormData(f).get('description').trim(),phaseId:new FormData(f).get('phaseId')||'',createdAt:new Date().toISOString()};state.decks.unshift(d);persist();logActivity(`Created flashcard deck: ${d.name}`,'▤');selectedDeckId=d.id;dialog.close();route='flashcards';render();toast('Deck created.')}
 else if(formKind==='card')await saveCard(f,id);else if(formKind==='resource'){const data=new FormData(f),conceptId=f.dataset.concept,list=state.userResources[conceptId]||[],entry={id:id||uid(),title:String(data.get('title')).trim(),url:String(data.get('url')).trim(),type:data.get('type'),language:data.get('language'),description:String(data.get('description')).trim(),updatedAt:new Date().toISOString()};const index=list.findIndex(x=>x.id===id);if(index>=0)list[index]=entry;else list.push(entry);state.userResources[conceptId]=list;persist();dialog.close();conceptDialog(conceptId);toast('Personal reference saved.')}
 else if(formKind==='shortcut'){const data=new FormData(f),s=state.settings.shortcuts.find(x=>x.id===id);Object.assign(s,{name:String(data.get('name')).trim(),url:String(data.get('url')).trim(),description:String(data.get('description')).trim()});persist();dialog.close();renderProfile();toast('Workspace shortcut updated.')}
});

$('#dialogClose').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});$('#themeToggle').addEventListener('click',()=>{state.settings.theme=state.settings.theme==='dark'?'light':'dark';persist();profileTop();render()});$('#menuToggle').addEventListener('click',e=>{const n=$('.desktop-nav'),open=n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.setAttribute('aria-label',open?'Close navigation':'Open navigation')});document.addEventListener('click',e=>{const a=e.target.closest('a[data-route]');if(a){e.preventDefault();$('.desktop-nav')?.classList.remove('open');setRoute(a.dataset.route)}});window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['welcome','home','roadmap','tasks','flashcards','quizzes','profile','admin'].includes(next)&&next!==route)setRoute(next)});

window.addEventListener('online',updateConnection);window.addEventListener('offline',updateConnection);function updateConnection(){const b=$('#connectionBadge'),online=navigator.onLine;b.classList.toggle('offline',!online);b.innerHTML=`<i></i>${online?'Online':'Offline · saved here'}`}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;const b=$('#installBanner');if(b)b.classList.add('ready')});window.addEventListener('appinstalled',()=>toast('Learn / YouCode was installed.'));
async function init(){const defaults=freshState();state=await loadState();state={...defaults,...state,profile:{...defaults.profile,...state.profile},settings:{...defaults.settings,...state.settings,shortcuts:state.settings?.shortcuts?.length?state.settings.shortcuts:defaults.settings.shortcuts}};curriculum=structuredClone(CURRICULUM);if(Array.isArray(state.admin?.phases))curriculum=state.admin.phases;const hash=location.hash.slice(1);if(['welcome','home','roadmap','tasks','flashcards','quizzes','profile','admin'].includes(hash))route=hash;profileTop();updateConnection();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(reg=>{reg.addEventListener('updatefound',()=>{const w=reg.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)toast('An app update is ready. Refresh to use it.')})})}).catch(()=>{});}
init();
